#!/usr/bin/env bash
set -e
mkdir -p ~/gastrodex-live && cd ~/gastrodex-live
echo "📥 Entpacke Gastrodex Live PWA..."
cat << 'EOF' > deploy_pkg.b64

EOF
base64 -d deploy_pkg.b64 > deploy_pkg.zip
unzip -o -q deploy_pkg.zip
rm -f deploy_pkg.b64 deploy_pkg.zip
echo "🚀 Starte Firebase Deployment..."
firebase deploy --project gastrodex-823d7 --only hosting
echo ""
echo "🎉 ERFOLGREICH DEPLOYT!"
echo "Deine Web-App ist jetzt live unter: https://gastrodex-823d7.web.app"
